def generic_upgrades(rev, extra):
    u=[('marketing','Marketing campaign',round(rev*.08/500)*500,{'demand':.12},'+12% demand'),('efficiency','Efficiency program',round(rev*.1/500)*500,{'margin':.03},'+3% margin'),('insurance','Business insurance',round(rev*.06/500)*500,{'mitigate':.5},'halves risk losses')]
    if extra: u.append((extra[0],extra[1],round(rev*.14/500)*500,extra[2],extra[3]))
    return [dict(id=i,name=n,cost=max(500,c),effect=e,desc=d) for i,n,c,e,d in u]
def risks_of(rs):
    base=[('lawsuit','Customer lawsuit',.05,.04,-4),('breakin','Break-in / theft',.06,.015,-1)]
    return [dict(id=i,label=l,p=p,cost=c,rep=r) for i,l,p,c,r in base+list(rs)]
types={}
print('%-14s %9s %8s %8s %7s %8s' % ('type','startcost','rev','profit','pm','rent'))
for a,k in S:
    (id,name,icon,group,minAge,sector,rev,ticket,cogs,pm,unit,equip,roles,req,fee,blurb,xu,names,xr)=a
    N0=rev/ticket; eqs=[]
    for i,(eid,en,cost) in enumerate(equip):
        eqs.append(dict(id=eid,name=en,cost=cost,cap=round(N0*(0.58 if i<2 else 0.5),1),**({'starter':1} if i<2 else {})))
    rl=[]
    for rid,rn,base,starter,share in roles:
        cap = N0*1.15*share/max(1,starter) if starter else N0*0.3
        rl.append(dict(id=rid,name=rn,base=base,cap=round(cap,1),starter=starter))
    wages=sum(r['base']*1.03*r['starter'] for r in rl); upkeep=sum(e['cost']*e.get('starter',0) for e in eqs)*.06
    gross=rev*(1-cogs); rent=gross-wages-upkeep-pm*rev; floor=rev*.02
    if rent<floor: rent=floor
    prof=gross-wages-upkeep-rent
    types[id]=dict(kind='shop',x=True,name=name,icon=icon,group=group,blurb=blurb,minAge=minAge,sector=sector,fee=fee,ticket=ticket,cogs=cogs,rent=round(rent/500)*500,baseDemand=round(N0*1.35,1),unit=unit,equip=eqs,roles=rl,req=req,risks=risks_of(xr),upgrades=generic_upgrades(rev,xu),names=names)
    print('%-14s %9d %8d %8d %6.1f%% %8d' % (id, fee+sum(e['cost']*e.get('starter',0) for e in eqs), rev, prof, 100*prof/rev, rent))
    if prof<=0: print('WARN',id,prof)
for f in FLEETS:
    fid=f['id']; vehicle=dict(name=f['vehicle'],cost=f['vcost'],rev=f['rev'],fuel=f['fuel'],ins=f['ins'],maint=f['maint'],acc=f['acc'],accCost=f['acccost'])
    rl=[dict(id='driver',name='Driver',base=f['wage'],cap=0,starter=f['start']),dict(id='dispatcher',name='Dispatcher',base=46000,cap=0,starter=0)]
    eqs=[dict(id='depot',name='Depot bay block (+4 vehicles)',cost=60000,cap=0,starter=1)]
    prof=f['start']*(f['rev']-f['fuel']-f['ins']-f['maint']-f['wage']*1.03)
    types[fid]=dict(kind='shop',x=True,name=f['name'],icon=f['icon'],group=f['group'],blurb=f['blurb'],minAge=f['minAge'],sector=f['sector'],fee=f['fee'],ticket=1,cogs=0,rent=9000,baseDemand=1,unit=f['unit'],equip=eqs,roles=rl,req=f['req'],risks=risks_of([('fuel','Fuel price spike',.15,.06,0),('driver','Driver shortage',.12,.04,-3)]),upgrades=generic_upgrades(f['start']*f['rev'],('telematics','Telematics & dispatch software',{'demand':.1,'mitigate':.2},'+10% demand, fewer accidents')),names=f['names'],fleet=dict(vehicle=vehicle,start=f['start'],maxBase=f['maxbase'],perDepot=4))
    print('%-14s %9d %8d %8d  (fleet, %d vehicles, before rent/depot)' % (fid, f['fee']+60000+f['start']*f['vcost'], f['start']*f['rev'], prof, f['start']))
    assert prof>0
patch={}
for k,p in PATCH.items():
    patch[k]=dict(x=True,icon=p['icon'],group=p['group'],minAge=p['minAge'],blurb=p['blurb'],req=p['req'],risks=risks_of(p['risks']),upgrades=[dict(id=i,name=n,cost=round(c*1000000/1000)*1000 if c<1 else c,effect=e,desc=d) for i,n,c,e,d in [(u[0],u[1],int(u[2]*300000),u[3],u[4]) for u in p['upgrades']]]+generic_upgrades(300000,None)[2:],names=p['names'])
json.dump(dict(types=types,patch=patch),open(OUT,'w'),indent=1,ensure_ascii=False)
print(len(types),'new types +',len(patch),'patched')
